43	  BOARD_DEFAULT_SORT,
44	} from "../../lib/backend-list-params";
45	
46	export type BoardContextValue = {
47	  workspaceDetail: WorkspaceDetail;
48	  features: ParsedFeature[];
49	  trackedFeatures: ParsedFeature[];
50	  loading: boolean;
51	  error: BoardLoadError | null;
52	  reload: () => void;
53	  syncing: boolean;
54	  syncError: BoardLoadError | null;
