57	  openTaskTabNewSession: (task: ParsedTask) => void;
58	  openFeatureTab: (feature: ParsedFeature) => void;
59	  openFeatureTabNewSession: (feature: ParsedFeature) => void;
60	
61	  boardMode: BoardMode;
62	  setBoardMode: (mode: BoardMode) => void;
63	
64	  // Task Mode search/filter
65	  taskSearchQuery: string;
66	  setTaskSearchQuery: (query: string) => void;
67	  taskActiveFilters: ActiveFilters;
68	  setTaskActiveFilters: (filters: ActiveFilters) => void;
69	
