71	  featureSearchQuery: string;
72	  setFeatureSearchQuery: (query: string) => void;
73	  featureActiveFilters: FeatureActiveFilters;
74	  setFeatureActiveFilters: (filters: FeatureActiveFilters) => void;
75	
76	  // Aliases kept for existing Task Mode consumers
77	  searchQuery: string;
78	  setSearchQuery: (query: string) => void;
79	  activeFilters: ActiveFilters;
80	  setActiveFilters: (filters: ActiveFilters) => void;
81	
82	  expandedFeatureIds: Set<string>;
83	  toggleFeature: (featureId: string) => void;
84	
85	  // Backend search results (null = use workspace detail)
86	  backendTaskResults: ParsedFeature[] | null;
87	  backendFeatureResults: ParsedFeature[] | null;
88	  taskSearching: boolean;
89	  featureSearching: boolean;
90	  taskSearchError: BoardLoadError | null;
91	  featureSearchError: BoardLoadError | null;
92	
93	  // Pagination state per mode
94	  taskPage: number;
95	  setTaskPage: (page: number) => void;
96	  featurePage: number;
