131	    },
132	  );
133	  const { trackedFeatures, reload: reloadTracking } = usePullRequestTaskData(
134	    workspaceDetail.id,
135	  );
136	
137	  const {
138	    syncCurrentWorkspace,
139	    syncingWorkspace: syncing,
140	    syncError: wsyncError,
141	    openTaskTab: wsOpenTaskTab,
142	    openFeatureTab: wsOpenFeatureTab,
143	  } = useWorkspaceActionsContext();
144	
145	  const [boardMode, setBoardModeState] = useState<BoardMode>(
146	    () => getStoredBoardMode() ?? getDefaultBoardMode(),
147	  );
148	  const [taskSearchQuery, setTaskSearchQuery] = useState("");
149	  const [featureSearchQuery, setFeatureSearchQuery] = useState("");
150	  const [taskActiveFilters, setTaskActiveFiltersState] =
151	    useState<ActiveFilters>(() => ({
152	      statuses: getStoredStatusFilter() ?? getDefaultStatusFilter(),
153	    }));
154	  const [featureActiveFilters, setFeatureActiveFiltersState] =
155	    useState<FeatureActiveFilters>(() => ({
156	      statuses:
157	        getStoredFeatureStatusFilter() ?? getDefaultFeatureStatusFilter(),
158	    }));
159	  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
160	    () => new Set(),
161	  );
162	  const [taskPage, setTaskPage] = useState(1);
163	  const [featurePage, setFeaturePage] = useState(1);
164	  const [taskLimit, setTaskLimit] = useState(BOARD_DEFAULT_LIMIT);
165	  const [featureLimit, setFeatureLimit] = useState(BOARD_DEFAULT_LIMIT);
166	
167	  // Task Mode always uses the feature-task API. Build params from current
168	  // search/filter/pagination state. Sort is fixed at task_id_asc per spec.
169	  const deferredTaskSearchQuery = useDeferredValue(taskSearchQuery);
170	  const deferredFeatureSearchQuery = useDeferredValue(featureSearchQuery);
171	  const trimmedTaskQuery = deferredTaskSearchQuery.trim();
172	
173	  // Reset page to 1 when search query, filters, or limit change
174	  const prevTaskQueryRef = useRef(trimmedTaskQuery);
175	  const prevTaskStatusRef = useRef(taskActiveFilters.statuses.join(","));
176	  const prevTaskLimitRef = useRef(taskLimit);
177	  useEffect(() => {
178	    const currentStatus = taskActiveFilters.statuses.join(",");
179	    if (
180	      trimmedTaskQuery !== prevTaskQueryRef.current ||
181	      currentStatus !== prevTaskStatusRef.current ||
182	      taskLimit !== prevTaskLimitRef.current
183	    ) {
184	      setTaskPage(1);
185	    }
186	    prevTaskQueryRef.current = trimmedTaskQuery;
187	    prevTaskStatusRef.current = currentStatus;
188	    prevTaskLimitRef.current = taskLimit;
189	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskLimit]);
190	
191	  const taskModeParams = useMemo(() => {
192	    const status =
193	      taskActiveFilters.statuses.length > 0
194	        ? taskActiveFilters.statuses.join(",")
195	        : undefined;
196	    return {
197	      title: trimmedTaskQuery || undefined,
198	      status,
199	      page: taskPage,
200	      limit: taskLimit,
201	      sort: "task_id_asc" as const,
202	    };
203	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskPage, taskLimit]);
204	
205	  const {
206	    data: featureTaskData,
207	    loading: taskSearching,
208	    error: featureTaskError,
209	  } = useFeatureTaskList(
210	    boardMode === "task" ? workspaceDetail.id : null,
211	    taskModeParams,
212	  );
213	
214	  const backendTaskResults = useMemo<ParsedFeature[] | null>(() => {
215	    if (boardMode !== "task") return null;
216	    if (!featureTaskData) return null;
217	    return adaptFeatureWithTasksToFeatures(featureTaskData.features);
218	  }, [boardMode, featureTaskData]);
219	
220	  const taskPagination = useMemo(() => {
221	    if (!featureTaskData) return null;
222	    return {
223	      total: featureTaskData.total,
224	      page: featureTaskData.page,
225	      limit: featureTaskData.limit,
226	    };
227	  }, [featureTaskData]);
228	
229	  const taskSearchError = useMemo(() => {
230	    if (!featureTaskError) return null;
231	    return {
232	      kind: "network_error" as const,
233	      message: featureTaskError.message ?? "Task Mode fetch failed",
234	      retryable: featureTaskError.retryable,
235	    };
236	  }, [featureTaskError]);
237	
238	  const trimmedFeatureQuery = deferredFeatureSearchQuery.trim();
239	
240	  // Feature-mode backend search activates when search text is present OR the
241	  // status filter is a non-default subset.  All-feature-statuses-selected
242	  // means no effective filter — fall back to the workspace root payload.
243	  const featureStatusFilterActive =
244	    featureActiveFilters.statuses.length > 0 &&
245	    !isAllFeatureStatusFilterSelected(featureActiveFilters.statuses);
246	  const featureSearchActive =
247	    boardMode === "feature" &&
248	    (trimmedFeatureQuery.length > 0 || featureStatusFilterActive);
249	
250	  const prevFeatureQueryRef = useRef(trimmedFeatureQuery);
251	  const prevFeatureStatusRef = useRef(
252	    featureActiveFilters.statuses.join(","),
253	  );
254	  const prevFeatureLimitRef = useRef(featureLimit);
255	  useEffect(() => {
256	    const currentStatus = featureActiveFilters.statuses.join(",");
257	    if (
258	      trimmedFeatureQuery !== prevFeatureQueryRef.current ||
259	      currentStatus !== prevFeatureStatusRef.current ||
260	      featureLimit !== prevFeatureLimitRef.current
261	    ) {
262	      setFeaturePage(1);
263	    }
264	    prevFeatureQueryRef.current = trimmedFeatureQuery;
265	    prevFeatureStatusRef.current = currentStatus;
