267	  }, [trimmedFeatureQuery, featureActiveFilters.statuses, featureLimit]);
268	
269	  const featureSearchParams = useMemo(() => {
270	    if (!featureSearchActive) return {};
271	
272	    const status = featureStatusFilterActive
273	      ? featureActiveFilters.statuses.join(",")
274	      : undefined;
275	
276	    return {
277	      title: trimmedFeatureQuery || undefined,
278	      status,
279	      page: featurePage,
280	      limit: featureLimit,
281	      sort: BOARD_DEFAULT_SORT,
282	    };
283	  }, [trimmedFeatureQuery, featureActiveFilters.statuses, featurePage, featureSearchActive, featureStatusFilterActive, featureLimit]);
284	
285	  const {
286	    results: backendFeatureResults,
287	    searching: featureSearching,
288	    searchError: featureSearchError,
289	    pagination: featurePagination,
290	  } = useBackendFeatureSearch(workspaceDetail.id, featureSearchParams);
291	
292	  const toggleFeature = useCallback((featureId: string) => {
293	    setExpandedFeatureIds((prev) => {
294	      const next = new Set(prev);
295	      if (next.has(featureId)) {
296	        next.delete(featureId);
297	      } else {
298	        next.add(featureId);
299	      }
300	      return next;
301	    });
302	  }, []);
303	
304	  const reloadAll = useCallback(() => {
305	    reload();
306	    reloadTracking();
307	  }, [reload, reloadTracking]);
308	
309	  const reloadAllRef = useRef(reloadAll);
310	  useEffect(() => {
311	    reloadAllRef.current = reloadAll;
312	  }, [reloadAll]);
313	
314	  useEffect(() => {
315	    const id = setInterval(() => {
316	      reloadAllRef.current();
317	    }, 60_000);
318	    return () => clearInterval(id);
319	  }, []);
320	
321	  const handleSetBoardMode = useCallback((mode: BoardMode) => {
322	    saveBoardMode(mode);
323	    setBoardModeState(mode);
324	  }, []);
325	
326	  const handleSetTaskActiveFilters = useCallback((filters: ActiveFilters) => {
327	    saveStatusFilter(filters.statuses);
328	    setTaskActiveFiltersState(filters);
329	  }, []);
330	
331	  const handleSetFeatureActiveFilters = useCallback(
332	    (filters: FeatureActiveFilters) => {
333	      saveFeatureStatusFilter(filters.statuses);
