377	      wsOpenFeatureTab({
378	        featureId: feature.backendId,
379	        featureName: feature.id,
380	        title: feature.title || feature.id,
381	      });
382	    },
383	    [wsOpenFeatureTab],
384	  );
385	
386	  const openFeatureTabNewSession = useCallback(
387	    (feature: ParsedFeature) => {
388	      if (!feature.backendId) return;
389	      wsOpenFeatureTab(
390	        {
391	          featureId: feature.backendId,
392	          featureName: feature.id,
393	          title: feature.title || feature.id,
394	        },
395	        { forceNewSession: true },
396	      );
397	    },
398	    [wsOpenFeatureTab],
399	  );
400	
401	  // Map workspace sync error to BoardLoadError shape
402	  const syncError = useMemo<BoardLoadError | null>(
403	    () =>
404	      wsyncError
405	        ? {
406	            kind: "network_error",
407	            message: wsyncError.message ?? "Sync failed",
408	            retryable: wsyncError.retryable,
409	          }
410	        : null,
411	    [wsyncError],
412	  );
413	
414	  const value = useMemo<BoardContextValue>(
415	    () => ({
416	      workspaceDetail,
417	      features,
418	      trackedFeatures,
419	      loading,
420	      error,
421	      reload: reloadAll,
422	      syncing,
423	      syncError,
424	      syncBoard,
425	
426	      boardMode,
427	      setBoardMode: handleSetBoardMode,
428	
429	      taskSearchQuery,
430	      setTaskSearchQuery,
431	      taskActiveFilters,
432	      setTaskActiveFilters: handleSetTaskActiveFilters,
433	
434	      featureSearchQuery,
435	      setFeatureSearchQuery,
436	      featureActiveFilters,
437	      setFeatureActiveFilters: handleSetFeatureActiveFilters,
438	
439	      // Aliases for existing Task Mode consumers
440	      searchQuery: taskSearchQuery,
441	      setSearchQuery: setTaskSearchQuery,
442	      activeFilters: taskActiveFilters,
443	      setActiveFilters: handleSetTaskActiveFilters,
444	
445	      expandedFeatureIds,
446	      toggleFeature,
447	
448	      backendTaskResults,
449	      backendFeatureResults,
450	      taskSearching,
451	      featureSearching,
452	      taskSearchError,
453	      featureSearchError,
454	      openTaskTab,
455	      openTaskTabNewSession,
456	      openFeatureTab,
457	      openFeatureTabNewSession,
458	
459	      taskPage,
460	      setTaskPage,
461	      featurePage,
462	      setFeaturePage,
463	      taskPagination,
464	      featurePagination,
465	
466	      taskLimit,
467	      setTaskLimit,
468	      featureLimit,
469	      setFeatureLimit,
470	    }),
471	    [
472	      workspaceDetail,
473	      features,
474	      trackedFeatures,
475	      loading,
476	      error,
477	      reloadAll,
478	      syncing,
479	      syncError,
480	      syncBoard,
481	      boardMode,
482	      handleSetBoardMode,
483	      taskSearchQuery,
484	      taskActiveFilters,
485	      handleSetTaskActiveFilters,
486	      featureSearchQuery,
487	      featureActiveFilters,
488	      handleSetFeatureActiveFilters,
489	      expandedFeatureIds,
490	      toggleFeature,
491	      backendTaskResults,
492	      backendFeatureResults,
493	      taskSearching,
494	      featureSearching,
495	      taskSearchError,
496	      featureSearchError,
497	      openTaskTab,
498	      openTaskTabNewSession,
499	      openFeatureTab,
500	      openFeatureTabNewSession,
501	
502	      taskPage,
503	      featurePage,
504	      taskPagination,
505	      featurePagination,
506	
507	      taskLimit,
508	      featureLimit,
509	    ],
510	  );
511	
512	  const trackingValue = useMemo<BoardTrackingContextValue>(
513	    () => ({
514	      trackedFeatures,
515	      openTaskTab,
516	      openTaskTabNewSession,
