520	
521	  return (
522	    <BoardContext.Provider value={value}>
523	      <BoardTrackingContext.Provider value={trackingValue}>
524	        {children}
525	      </BoardTrackingContext.Provider>
526	    </BoardContext.Provider>
527	  );
528	}
